const conv = ($input.first().json.conversations) || [];
const out = [];
for (const c of conv) {
  if (c.lastMessageDirection !== 'inbound') continue;
  const body = (c.lastMessageBody || '').trim();
  if (!body) continue;
  out.push({ json: { conversationId: c.id, contactId: c.contactId, email: c.email || null, ts: c.lastMessageDate, body: body.slice(0, 2000) } });
}
return out;

const meta = $('Extract inbound replies').all();
const resps = $input.all();
function norm(t){ t=String(t||'').toLowerCase(); if(t.includes('opt'))return 'Opt-out'; if(t.includes('posit'))return 'Positive'; if(t.includes('negat'))return 'Negative'; return 'Neutral'; }
const replies = [];
for (let i=0;i<meta.length;i++){ let txt=''; try{ txt=resps[i].json.content[0].text; }catch(e){ txt=''; } replies.push({ contactId: meta[i].json.contactId, sentiment: norm(txt), ts: meta[i].json.ts }); }
return [{ json: { replies } }];

const replies = $('Collect classified').first().json.replies || [];
const opps = ($input.first().json.opportunities) || [];
const won = new Set(opps.filter(o => o.status === 'won').map(o => o.contactId));

const counts = {};
for (const r of replies) {
  const d = new Date(Number(r.ts));
  const ym = d.getUTCFullYear() + '-' + String(d.getUTCMonth() + 1).padStart(2, '0');
  const key = ym + '|' + r.sentiment;
  counts[key] = (counts[key] || 0) + 1;
}
const p_rows = Object.entries(counts).map(([k, v]) => { const [payout_month, sentiment] = k.split('|'); return { payout_month, sentiment, reply_count: v }; });

const posContacts = new Set(replies.filter(r => r.sentiment === 'Positive').map(r => r.contactId).filter(Boolean));
let advanced = 0;
for (const c of posContacts) if (won.has(c)) advanced++;

return [{ json: { p_location: 'htgHvVfBZ1WH3UpQoxaa', p_rows, p_positive_replies: posContacts.size, p_positive_advanced: advanced } }];
